  91.6667% { transform: translate(-25.000%, 6.699%); }
  95.8333% { transform: translate(-12.941%, 1.704%); }
  100% { transform: translate(-0.000%, 0.000%); }
}

/*
 * MobiusLoader: each ribbon segment gets its own inline
 * \`transform: rotate(<twist>deg)\`, and \`mobius-segment\` animated
 * \`rotate(var(--angle, 90deg))\`. The component never sets \`--angle\`, so
 * every segment snapped to the 90deg fallback and the ribbon collapsed
 * into a row of parallel dashes. Animate \`scale\` instead: it is its own
 * property, so the inline rotation survives.
 */
@keyframes mobius-segment {
  0%, 100% { opacity: 0.3; scale: 1; }
  50%      { opacity: 1;   scale: 1.2; }
}
